public static class VenueFinaleCheck {
 static string log;static void Check(bool ok,string text){log+=(ok?"PASS ":"FAIL ")+text+"\n";File.WriteAllText("Logs/Venue-check.txt",log);if(!ok)throw new Exception(text);}
 static IEnumerator Wait(float t){float end=Time.time+t;while(Time.time<end)yield return null;}
 static IEnumerator Key(Key key){InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(key));yield return null;yield return null;InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());yield return null;}
 // 전투와 추격 자체는 별도로 검증하고, 연결 검사에서는 NPC 몸 충돌을 분리한다.
 static IEnumerator Walk(VenueFinale m,Vector3 at){var p=m.Player;var path=new NavMeshPath();Check(NavMesh.CalculatePath(p.transform.position,at,NavMesh.AllAreas,path)&&path.status==NavMeshPathStatus.PathComplete,"connected route to "+at);var cc=p.GetComponent<CharacterController>();var disabled=new System.Collections.Generic.List<Collider>();try{foreach(var corner in path.corners.Skip(1)){float end=Time.time+35;while(Vector2.Distance(new(p.transform.position.x,p.transform.position.z),new(corner.x,corner.z))>.4f){if(Time.time>end)throw new Exception("blocked "+p.transform.position+" -> "+corner);foreach(var npc in UnityEngine.Object.FindObjectsByType<CitizenCombat>(FindObjectsSortMode.None))foreach(var body in npc.GetComponentsInChildren<Collider>())if(body.enabled){disabled.Add(body);body.enabled=false;}var d=corner-p.transform.position;d.y=0;p.View.transform.rotation=Quaternion.LookRotation(d);cc.Move((d.normalized*6+Vector3.down*3)*Time.deltaTime);yield return null;}}}finally{foreach(var body in disabled)if(body)body.enabled=true;}}
 static void SafeEnemies(VenueFinale m){foreach(var e in m.Enemies)e.ExternalAttackControl=true;}
 public static IEnumerator Vehicle(){log="First event boarding visual check\n";yield return Wait(.5f);var m=VenueFinale.Current;var recon=m.preparation.preparation;var b=recon.delivery.broker;typeof(BrokerMission).GetProperty("State").SetValue(b,BrokerMission.Phase.Complete);typeof(SpecialOrderMission).GetProperty("State").SetValue(recon.delivery,SpecialOrderMission.Phase.Complete);typeof(BackdoorMission).GetProperty("State").SetValue(recon,BackdoorMission.Phase.Complete);typeof(MechanicMission).GetProperty("State").SetValue(m.preparation,MechanicMission.Phase.Complete);b.day.EnterNightPreparation();StoryPhoneInbox.Current.AutoOpenEnabled=false;typeof(VenueFinale).GetProperty("EventDay").SetValue(m,b.day.currentDay);Check(m.Begin(),"vehicle visual setup starts");m.SkipCinematic();typeof(VenueFinale).GetProperty("State").SetValue(m,VenueFinale.Phase.StreetEscape);typeof(VenueFinale).GetField("turned",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(m,true);m.PlacePlayer(m.carStand);yield return null;Check(m.Interact(),"board interaction works");yield return Wait(m.boardingSeconds*.5f);Check(!m.passenger.gameObject.activeSelf&&Vector3.Distance(m.cinema.transform.position,m.car.TransformPoint(new Vector3(-1.05f,1.12f,.16f)))<.4f,"boarding camera passes through driver doorway in first person");BrokerMissionCheck.Capture(b,"Venue-boarding",m.cinema);yield return Wait(m.boardingSeconds*.6f);Check(Vector3.Distance(m.cinema.transform.position,m.car.TransformPoint(m.getaway.eye))<.1f,"boarding hands off at driving eye without camera jump");Check(m.State==VenueFinale.Phase.Driving,"boarding finishes");yield return Wait(.4f);Check(!m.driver.gameObject.activeSelf,"mechanic is absent from getaway car");yield return Drive(m);m.SkipCinematic();Check(m.Completed&&!m.cinema.enabled,"visual check restores control");Check(m.getaway.HiddenTrafficCount==0&&UnityEngine.Object.FindObjectsByType<CarMov>(FindObjectsSortMode.None).Length>0,"traffic restored after completion");}
 public static IEnumerator Drive(VenueFinale m){
 var fill=UnityEngine.Object.FindFirstObjectByType<CityEveningVisibility>();Check(fill&&RenderSettings.ambientLight.b>=.149f,"evening city ambient fill active");var d=m.getaway;Check(d&&d.Driving&&!m.driver.gameObject.activeSelf,"manual drive active, mechanic absent");
 m.AbandonCar();Check(m.State==VenueFinale.Phase.Driving,"cannot abandon car before destination");Vector3 origin=m.car.position;yield return Wait(.3f);Check(Vector3.Distance(origin,m.car.position)<.05f,"no automatic movement without input");m.SkipCinematic();Check(m.State==VenueFinale.Phase.Driving,"cinematic skip cannot bypass driving");
 InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(UnityEngine.InputSystem.Key.W));yield return Wait(.8f);InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());Check(Vector3.Distance(origin,m.car.position)>1,"W moves getaway car, delta="+Vector3.Distance(origin,m.car.position)+" speed="+d.Speed+" blocker="+d.LastBlock);
 var freeze=m.car.position;Time.timeScale=0;yield return null;yield return null;Check(m.car.position==freeze,"pause freezes driving");Time.timeScale=1;
 BrokerMissionCheck.Capture(m.preparation.preparation.delivery.broker,"Venue-manual-cockpit",m.cinema);
 d.ExternalInput=true;var hands=d.GetComponent<PrologueDrivingHands>();Check(hands&&hands.arms.gameObject.activeSelf,"saved Synty driving arms visible");Check(Vector3.Distance(hands.leftHand.position,hands.leftGrip.position)<.08f&&Vector3.Distance(hands.rightHand.position,hands.rightGrip.position)<.08f,"hands remain on wheel grips");float rightHeight=hands.rightGrip.position.y;d.Input(0,.5f);yield return Wait(.2f);Check(hands.Angle>1&&hands.rightGrip.position.y<rightHeight,"right steering turns wheel clockwise from driver view");d.Input(0,0);

 yield return Curb(m);yield return Pedestrian(m);Check(!d.pursuit&&d.interception,"road guards replace pursuit cars");
 foreach(var point in d.route){float deadline=Time.time+30;while(Vector3.Distance(m.car.position,point.position)>3.5f&&Time.time<deadline){Vector3 delta=point.position-m.car.position;delta.y=0;float angle=Vector3.SignedAngle(m.car.forward,delta,Vector3.up);float toTurn=delta.magnitude;int k=System.Array.IndexOf(d.route,point);while(k+1<d.route.Length&&Vector3.Angle(delta,d.route[k+1].position-d.route[k].position)<15){toTurn+=Vector3.Distance(d.route[k+1].position,d.route[k].position);k++;}d.Input(Mathf.Abs(angle)>40?.18f:(toTurn>19&&Mathf.Abs(angle)<15?.98f:.3f),Mathf.Clamp(angle/25,-1,1));yield return null;}Check(Vector3.Distance(m.car.position,point.position)<=3.5f,"drivable checkpoint "+point.position+" from "+m.car.position+" blocked="+d.LastBlock);}
 d.Input(0,0);yield return Wait(6);Check(d.interception.Spawned==0&&d.interception.Shots==0,"no roadside shooting waves during getaway");Check(d.CanAbandon,"must park at designated location");var exitStart=m.cinema.transform.position;m.AbandonCar();Check(Vector3.Distance(exitStart,m.cinema.transform.position)<.001f&&!m.passenger.gameObject.activeSelf,"exit begins from current first-person camera without body duplicate");Check(m.State==VenueFinale.Phase.Abandoning&&!d.Driving,"parked car can be abandoned");yield return Wait(.7f);Check(Vector3.Distance(m.cinema.transform.position,m.car.TransformPoint(m.getaway.eye))<1,"exit camera stays near driver seat during door opening");BrokerMissionCheck.Capture(m.preparation.preparation.delivery.broker,"Venue-abandon-car",m.cinema);yield return Wait(1.35f);Check(Vector3.Distance(m.cinema.transform.position,m.car.TransformPoint(new Vector3(-1.85f,1.65f,.16f)))<.1f,"exit reaches standing eye outside driver door");BrokerMissionCheck.Capture(m.preparation.preparation.delivery.broker,"Venue-exit-standing",m.cinema);m.SkipCinematic();Check(m.State==VenueFinale.Phase.Debrief,"abandonment leads to shop return");
 Check(Vector3.Distance(m.Player.transform.position,m.safePoint.position)<2&&m.fade.color.a>.95f,"black transition actually returns player to shop before dialogue");yield return Wait(1.7f);var mingi=m.preparation.preparation.delivery.kitchen.actor;var target=mingi.position+Vector3.up*1.45f;Check(mingi.gameObject.activeInHierarchy&&Vector3.Angle(m.cinema.transform.forward,target-m.cinema.transform.position)<3,"homecoming camera faces visible Mingi at player eye level");Check(Vector3.Angle(mingi.forward,Vector3.ProjectOnPlane(m.Player.transform.position-mingi.position,Vector3.up))<5,"Mingi faces returned player");Check(!m.fade.gameObject.activeSelf&&System.Text.RegularExpressions.Regex.Replace(m.subtitle.text,"<.*?>","")==m.closing[1],"dialogue begins after shop fade-in");BrokerMissionCheck.Capture(m.preparation.preparation.delivery.broker,"Venue-homecoming",m.cinema);
 }
 public static IEnumerator Curb(VenueFinale m){var d=m.getaway;var origin=m.car.position;var rotation=m.car.rotation;d.Stop();var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.name="Sidewalk test";floor.transform.position=new Vector3(2000,0,2000);floor.transform.localScale=new Vector3(20,.2f,30);var curb=GameObject.CreatePrimitive(PrimitiveType.Cube);curb.name="Sidewalk raised test";curb.transform.position=new Vector3(2000,.3f,2005);curb.transform.localScale=new Vector3(20,.4f,10);m.car.SetPositionAndRotation(new Vector3(2000,.14f,1997),Quaternion.identity);Physics.SyncTransforms();d.Begin();d.ExternalInput=true;d.Input(.4f,0);float deadline=Time.time+3;while(m.car.position.z<2005&&Time.time<deadline)yield return null;Check(m.car.position.z>2002&&m.car.position.y>.4f,"car climbs raised sidewalk without stopping: "+m.car.position+" "+d.LastBlock);d.Stop();UnityEngine.Object.Destroy(floor);UnityEngine.Object.Destroy(curb);m.car.SetPositionAndRotation(origin,rotation);d.Begin();d.ExternalInput=true;}
 public static IEnumerator Pedestrian(VenueFinale m){var d=m.getaway;Vector3 start=m.car.position;Quaternion facing=m.car.rotation;int hits=d.PedestrianHits;var person=UnityEngine.Object.Instantiate(m.preparation.enemyTemplate,start+m.car.forward*4,facing);person.missionEnemy=false;person.gameObject.SetActive(true);yield return null;person.Npc.ExternalControl=true;person.GetComponent<NavMeshAgent>().enabled=false;person.transform.position=start+m.car.forward*4;Physics.SyncTransforms();d.ExternalInput=true;d.Input(.4f,0);float until=Time.time+3;while(!person.Npc.IsDead&&Time.time<until)yield return null;Check(person.Npc.IsDead&&d.PedestrianHits>hits,"car collision launches NPC into ragdoll: car="+m.car.position+" npc="+person.transform.position+" block="+d.LastBlock+" hits="+d.PedestrianHits);var center=person.Npc.RagdollCenter.position;yield return Wait(.3f);var flight=person.Npc.RagdollCenter.position-center;Check(Vector3.Dot(flight,facing*Vector3.forward)>1.2f,"ragdoll travels forward after impact: "+flight);BrokerMissionCheck.Capture(m.preparation.preparation.delivery.broker,"Venue-forward-impact",m.cinema);yield return Wait(.1f);Check(Vector3.Distance(start,m.car.position)>5&&d.Speed>2,"car continues through NPC instead of stopping");var police=UnityEngine.Object.FindFirstObjectByType<PoliceManager>();int before=UnityEngine.Object.FindObjectsByType<PoliceControl>(FindObjectsSortMode.None).Length;police.SpawnPoliceOnAccidentRefused();police.SpawnPoliceGroup(3);Check(police.SpawnArmedSupport(m.Player.transform)==null,"mission suppresses armed police dispatch");yield return null;Check(UnityEngine.Object.FindObjectsByType<PoliceControl>(FindObjectsSortMode.None).Length==before,"mission suppresses regular police dispatch");UnityEngine.Object.Destroy(person.gameObject);d.Stop();m.car.SetPositionAndRotation(start,facing);d.Begin();d.ExternalInput=true;}
 public static IEnumerator Ram(VenueFinale m){var d=m.getaway;var p=d.pursuit;Check(d.HiddenTrafficCount>0&&UnityEngine.Object.FindObjectsByType<CarMov>(FindObjectsSortMode.None).Length==0,"mission hides ordinary traffic");var origin=m.car.position;var rotation=m.car.rotation;d.Stop();m.car.SetPositionAndRotation(new Vector3(92.36f,.04f,-3.79f),Quaternion.identity);d.Begin();d.ExternalInput=true;d.Input(.36f,0);float until=Time.time+9;while(p.RamHits==0&&Time.time<until)yield return null;Check(p.RamHits>0,"side ram contacts player, attempts="+p.RamAttempts+" phases="+string.Join(",",p.cars.Select(c=>c.ramPhase.ToString())));Check(d.ShakeRemaining>0&&d.Impacts>0&&m.sound.isPlaying,"ram triggers impact sound and camera shake");Check(!d.ReceiveSideImpact(Vector3.right),"continuous contact cannot repeatedly stun player");var carPositions=p.cars.Select(c=>c.model.position).ToArray();Time.timeScale=0;yield return null;yield return null;Check(p.cars.Select((c,i)=>c.model.position==carPositions[i]).All(v=>v),"pause freezes side attacks");Time.timeScale=1;BrokerMissionCheck.Capture(m.preparation.preparation.delivery.broker,"Venue-side-impact",m.cinema);d.Stop();m.car.SetPositionAndRotation(origin,rotation);d.Begin();d.ExternalInput=true;}
