 yield return Walk(m,m.deliveryTable.position+Vector3.back*2);yield return Key(UnityEngine.InputSystem.Key.F);Check(m.State==VenueFinale.Phase.Observe,"pizza physically deposited");if(m.stealth){m.stealth.enabled=false;foreach(var guard in m.stealth.guards){guard.enabled=false;guard.GetComponent<NavMeshAgent>().isStopped=true;}}yield return Walk(m,m.observeStand.position);m.Player.View.transform.LookAt(m.target.position+Vector3.up*1.4f);yield return null;Check(m.CanObserve(),"target visible from observation position");var speaker=m.target.GetComponent<VenueSpeakerPerformance>();Check(speaker,"speaker performance saved in scene");Quaternion speechRotation=m.target.localRotation;yield return Wait(.3f);Check(Quaternion.Angle(speechRotation,m.target.localRotation)>.01f,"speaker gestures and turns during observation");BrokerMissionCheck.Capture(broker,"Venue-observation");Time.timeScale=0;m.Observe(true,10);Check(m.ObservationProgress==0,"paused observation makes no progress");Time.timeScale=1;InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(UnityEngine.InputSystem.Key.F));yield return Wait(m.observeSeconds+.1f);InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());yield return null;Check(m.State==VenueFinale.Phase.Conversation,"held F opens overheard conversation");yield return Key(UnityEngine.InputSystem.Key.Space);Check(m.State==VenueFinale.Phase.Exposed&&m.IntelSecured,"evidence leads to discovery cinematic");yield return Key(UnityEngine.InputSystem.Key.Space);Check(m.State==VenueFinale.Phase.InteriorEscape&&m.Enemies.Length==(m.stealth?3:2),"escape starts with bounded first wave");DeveloperCheats.SetInvincible(true);Check(!m.ExitUnlocked,"escape blocked before combat");
 var enemy=m.Enemies[0];var animator=enemy.GetComponentInChildren<Animator>();float runDeadline=Time.time+2;while(animator.GetFloat("MoveSpeed")<.2f&&Time.time<runDeadline)yield return null;Check(animator.enabled&&animator.GetFloat("RunRate")>.1f&&animator.GetFloat("MoveSpeed")>.1f,"enemy running animator receives movement and nonzero playback rate");
